	CONSTRAINT "enterprise_asset_binding_interval_check" CHECK ("enterprise_asset_measurement_binding"."valid_from_utc" >= 0 AND ("enterprise_asset_measurement_binding"."valid_to_utc" IS NULL OR "enterprise_asset_measurement_binding"."valid_to_utc" > "enterprise_asset_measurement_binding"."valid_from_utc"))
);

CREATE TABLE "enterprise_asset" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "enterprise_asset_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9007199254740991 START WITH 1 CACHE 1),
	"tenant_id" bigint NOT NULL,
	"asset_id" text NOT NULL,
	"asset_code" text,
	"name" text NOT NULL,
	"category" text NOT NULL,
	"brand" text,
	"model" text,
	"remark" text,
	"status" text NOT NULL,
	"retired_time_utc" bigint,
	"state_reason" text,
	"creator_id" bigint NOT NULL,
	"updater_id" bigint,
	"create_time_utc" bigint NOT NULL,
	"update_time_utc" bigint,
	CONSTRAINT "enterprise_asset_tenant_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "enterprise_asset_safe_id" CHECK ("enterprise_asset"."id" BETWEEN -9007199254740991 AND 9007199254740991),
	CONSTRAINT "enterprise_asset_safe_tenant_id" CHECK ("enterprise_asset"."tenant_id" BETWEEN -9007199254740991 AND 9007199254740991),
	CONSTRAINT "enterprise_asset_safe_retired_time_utc" CHECK ("enterprise_asset"."retired_time_utc" BETWEEN -9007199254740991 AND 9007199254740991),
	CONSTRAINT "enterprise_asset_safe_creator_id" CHECK ("enterprise_asset"."creator_id" BETWEEN -9007199254740991 AND 9007199254740991),
	CONSTRAINT "enterprise_asset_safe_updater_id" CHECK ("enterprise_asset"."updater_id" BETWEEN -9007199254740991 AND 9007199254740991),
	CONSTRAINT "enterprise_asset_safe_create_time_utc" CHECK ("enterprise_asset"."create_time_utc" BETWEEN -9007199254740991 AND 9007199254740991),
	CONSTRAINT "enterprise_asset_safe_update_time_utc" CHECK ("enterprise_asset"."update_time_utc" BETWEEN -9007199254740991 AND 9007199254740991),
	CONSTRAINT "enterprise_asset_state_check" CHECK (("enterprise_asset"."status" = 'active' AND "enterprise_asset"."retired_time_utc" IS NULL) OR ("enterprise_asset"."status" = 'retired' AND "enterprise_asset"."retired_time_utc" IS NOT NULL)),
	CONSTRAINT "enterprise_asset_category_check" CHECK ("enterprise_asset"."category" IN ('host','disk','gpu','board','sensor','meter','other'))
);

